25	/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
26	 * given), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
27	 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
28	 * any number of "patrons": other people on the list, whose thrust added together is the person's
29	 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). A person may have a
30	 * "grade" (LOW, MID or HIGH; absent until given), from which their "weight" is 1, 3 or 5. "Load" is momentum times weight.
31	 * A person may have an "onset" date (absent until given); their "age" is the complete weeks from onset to the sheet's anchor.
32	 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the average of the
33	 * patrons' effective, rounded down (zero without patrons). "Influence" is effective plus clout.
34	 * A person may belong to any number of "regions": short codes typed in, like N1 or S2. A region's
35	 * "multiplier" comes from its first letter: N is 2, S is 3, any other is 1. "Reach" is the sum, over the
36	 * person's regions, of momentum times that region's multiplier. */
37	@Entity
38	@Table(name = "person")
39	public class Person {
40	
41	    /** The longest region code that can be stored. */
42	    public static final int REGION_MAX_LENGTH = 16;
43	
44	    @Id
45	    @GeneratedValue(strategy = GenerationType.IDENTITY)
46	    private Long id;
47	
48	    /** The person's id within their sheet; the id the user and the API see. */
49	    @Column(name = "local_id")
50	    private Long localId;
51	
52	    private String name;
53	
54	    private Integer alpha;
55	
56	    private Integer beta;
57	
58	    private Integer gamma;
59	
60	    @Enumerated(EnumType.STRING)
61	    private Grade grade;
62	
63	    private LocalDate onset;
64	
65	    private boolean active = true;
66	
67	    /** The id of the sheet the person belongs to; null for the unnamed sheet. */
68	    @Column(name = "sheet_id")
69	    private String sheetId;
70	
71	    @ManyToMany(fetch = FetchType.EAGER)
72	    @JoinTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"),
73	            inverseJoinColumns = @JoinColumn(name = "patron_id"))
74	    private Set<Person> patrons = new HashSet<>();
75	
76	    @ElementCollection(fetch = FetchType.EAGER)
77	    @CollectionTable(name = "person_region", joinColumns = @JoinColumn(name = "person_id"))
78	    @Column(name = "region")
79	    private Set<String> regions = new HashSet<>();
80	
81	    protected Person() {
82	    }
83	
84	    public Person(String sheetId, long localId, String name, Integer alpha, Integer beta, Integer gamma) {
85	        this.sheetId = sheetId;
86	        this.localId = localId;
87	        this.name = name;
88	        this.alpha = alpha;
89	        this.beta = beta;
90	        this.gamma = gamma;
91	    }
92	
93	    public Long getId() {
94	        return id;
95	    }
96	
97	    public Long getLocalId() {
98	        return localId;
99	    }
100	
101	    public String getSheetId() {
102	        return sheetId;
103	    }
104	
105	    public String getName() {
106	        return name;
107	    }
108	
109	    public Integer getAlpha() {
110	        return alpha;
111	    }
112	
113	    public void setAlpha(Integer alpha) {
114	        this.alpha = alpha;
115	    }
116	
117	    public Integer getBeta() {
118	        return beta;
119	    }
120	
121	    public void setBeta(Integer beta) {
122	        this.beta = beta;
123	    }
124	
125	    public Integer getGamma() {
126	        return gamma;
127	    }
128	
129	    public void setGamma(Integer gamma) {
130	        this.gamma = gamma;
131	    }
132	
133	    public Grade getGrade() {
134	        return grade;
135	    }
136	
137	    public void setGrade(Grade grade) {
138	        this.grade = grade;
139	    }
140	
141	    public boolean isActive() {
142	        return active;
143	    }
144	
145	    public void setActive(boolean active) {
146	        this.active = active;
147	    }
148	
149	    /** The regions, sorted ascending. */
150	    public List<String> getRegions() {
151	        return regions.stream().sorted().toList();
152	    }
153	
154	    public void setRegions(Collection<String> regions) {
155	        this.regions = new HashSet<>(regions);
156	    }
157	
158	    public LocalDate getOnset() {
159	        return onset;
160	    }
161	
162	    /** Age is the complete seven-day weeks from onset to the anchor (leftover days dropped), negative when onset is
163	     * after it and truncated toward zero; absent without an onset. */
164	    public Long getAge(LocalDate anchor) {
165	        return onset == null ? null : ChronoUnit.WEEKS.between(onset, anchor);
166	    }
167	
168	    /** Decay is momentum minus age; absent while either is absent. */
169	    public Long getDecay(LocalDate anchor) {
170	        Integer momentum = getMomentum();
171	        Long age = getAge(anchor);
172	        return momentum == null || age == null ? null : momentum - age;
173	    }
174	
175	    /** Weight comes from the grade: LOW 1, MID 3, HIGH 5; absent without a grade. */
176	    public Integer getWeight() {
177	        return grade == null ? null : grade.weight();
178	    }
179	
180	    /** The patrons, sorted by name. */
181	    public List<Person> getPatrons() {
182	        return patrons.stream()
183	                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
184	                .toList();
185	    }
186	
187	    public void setPatrons(Set<Person> patrons) {
188	        this.patrons = new HashSet<>(patrons);
189	    }
190	
191	    /** The derived values exist only once alpha, beta and gamma are all given. */
192	    private boolean complete() {
193	        return alpha != null && beta != null && gamma != null;
194	    }
195	
196	    /** Thrust is alpha multiplied by beta; absent until alpha, beta and gamma are all given. */
197	    public Integer getThrust() {
198	        return complete() ? alpha * beta : null;
199	    }
200	
201	    /** Drift is gamma minus alpha; absent until alpha, beta and gamma are all given. */
202	    public Integer getDrift() {
203	        return complete() ? gamma - alpha : null;
204	    }
205	
206	    /** Momentum is thrust plus three times drift; absent while either is absent. */
207	    public Integer getMomentum() {
208	        Integer thrust = getThrust();
209	        Integer drift = getDrift();
210	        return thrust == null || drift == null ? null : thrust + 3 * drift;
211	    }
212	
213	    /** Load is momentum times weight; absent while either is absent. */
214	    public Integer getLoad() {
215	        Integer momentum = getMomentum();
216	        Integer weight = getWeight();
217	        return momentum == null || weight == null ? null : momentum * weight;
218	    }
219	
220	    /** A region's multiplier from its first letter: N is 2, S is 3, any other is 1. */
221	    static int regionMultiplier(String region) {
222	        return switch (region.isEmpty() ? ' ' : Character.toUpperCase(region.charAt(0))) {
223	            case 'N' -> 2;
224	            case 'S' -> 3;
225	            default -> 1;
226	        };
227	    }
228	
229	    /** Reach is the sum over the regions of momentum times the region's multiplier; absent without momentum or regions. */
230	    public Integer getReach() {
231	        Integer momentum = getMomentum();
232	        if (momentum == null || regions.isEmpty()) {
233	            return null;
234	        }
235	        return regions.stream().mapToInt(r -> momentum * regionMultiplier(r)).sum();
236	    }
237	
238	    /** Backing is the sum of the patrons' thrust; absent without patrons or while any patron's thrust is absent. */
239	    public Integer getBacking() {
240	        if (patrons.isEmpty()) {
241	            return null;
242	        }
243	        int sum = 0;
244	        for (Person patron : patrons) {
245	            Integer thrust = patron.getThrust();
246	            if (thrust == null) {
247	                return null;
248	            }
249	            sum += thrust;
250	        }
251	        return sum;
252	    }
253	
254	    /** Net is momentum plus backing, counting backing as zero without patrons; absent with momentum, or with a patron whose thrust is absent. */
255	    public Integer getNet() {
256	        Integer momentum = getMomentum();
257	        if (momentum == null) {
258	            return null;
259	        }
260	        if (patrons.isEmpty()) {
261	            return momentum;
262	        }
263	        Integer backing = getBacking();
264	        return backing == null ? null : momentum + backing;
265	    }
266	
267	    /** Effective is net while active, and half of net rounded down while not active (absent while net is). */
268	    public Integer getEffective() {
269	        Integer net = getNet();
270	        if (net == null || active) {
271	            return net;
272	        }
273	        return Math.floorDiv(net, 2);
274	    }
275	
276	    /** Clout is the average of the patrons' effective, rounded down; zero without patrons, absent while any patron's effective is absent. */
277	    public Integer getClout() {
278	        int sum = 0;
279	        for (Person patron : patrons) {
280	            Integer effective = patron.getEffective();
281	            if (effective == null) {
282	                return null;
283	            }
284	            sum += effective;
285	        }
286	        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
287	    }
288	
289	    /** Influence is effective plus clout; absent while either is. */
290	    public Integer getInfluence() {
291	        Integer effective = getEffective();
292	        Integer clout = getClout();
293	        return effective == null || clout == null ? null : effective + clout;
294	    }
295	
296	    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
297	    public String getTier() {
298	        Integer momentum = getMomentum();
299	        if (momentum == null) {
300	            return null;
301	        }
302	        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
303	    }
304	}
